#include "beatglass/library/analysis_runner.hpp"
namespace beatglass::library { std::shared_ptr<library_detail::JobHandle> AnalysisRunner::submit(AnalysisOperation op,int priority){ return executor_.submit_tracked(priority,[op=std::move(op)](std::stop_token stop,const auto& progress){ if(stop.stop_requested()) return library_detail::TrackedState::cancelled; if(op.source.path.empty()||op.source.content_hash.empty()||op.identity.content_hash.empty()||op.source.content_hash!=op.identity.content_hash) return library_detail::TrackedState::failed; if(op.progress) op.progress(0,op.source.size_bytes); if(stop.stop_requested()) return library_detail::TrackedState::cancelled; if(!op.serialize||!op.verify) return library_detail::TrackedState::failed; auto verification=op.verify(stop); if(verification.outcome!=FileVerificationOutcome::match) return verification.outcome==FileVerificationOutcome::cancelled?library_detail::TrackedState::cancelled:library_detail::TrackedState::failed; auto result=op.serialize(); if(result.empty()) return library_detail::TrackedState::failed; progress(op.source.size_bytes); return library_detail::TrackedState::completed; }); } }
